+import { execFileSync } from "node:child_process";
+import { createHash } from "node:crypto";
+import * as fs from "node:fs";
+import * as os from "node:os";
+import * as path from "node:path";
+import { afterEach, describe, expect, it } from "vitest";
+import { gitChangedFiles, readProjectInfo, suggestTestCommands } from "../../src/features/verification";
+
+const temps: string[] = [];
+
+function tempDir(): string {
+	const dir = fs.mkdtempSync(path.join(os.tmpdir(), "vibe-verification-test-"));
+	temps.push(dir);
+	return fs.realpathSync(dir);
+}
+
+function git(cwd: string, args: string[]): string {
+	return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] });
+}
+
+function write(ws: string, file: string, content = "export const value = 1;\n"): void {
+	fs.mkdirSync(path.dirname(path.join(ws, file)), { recursive: true });
+	fs.writeFileSync(path.join(ws, file), content, "utf8");
+}
+
+function commit(ws: string): void {
+	git(ws, ["add", "-A"]);
+	git(ws, ["-c", "commit.gpgsign=false", "commit", "-qm", "fixture"]);
+}
+
+function repo(): string {
+	const ws = tempDir();
+	git(ws, ["init", "-q", "."]);
+	git(ws, ["config", "--local", "user.name", "verification test"]);
+	git(ws, ["config", "--local", "user.email", "test@example.com"]);
+	git(ws, ["config", "--local", "core.quotePath", "true"]);
+	write(ws, "tracked.txt", "initial\n");
+	commit(ws);
+	return ws;
+}
+
+function nodeProject(): string {
+	const ws = repo();
+	write(ws, "package.json", JSON.stringify({ scripts: { test: "vitest run" }, devDependencies: { vitest: "^3.0.0" } }));
+	write(ws, "src/계산.ts");
+	write(ws, "tests/계산.test.ts", 'import { value } from "../src/계산";\n');
+	write(ws, "tests/한글.test.ts");
+	commit(ws);
+	return ws;
+}
+
+function digest(file: string): string | null {
+	return fs.existsSync(file) ? createHash("sha256").update(fs.readFileSync(file)).digest("hex") : null;
+}
+
+function workingFiles(ws: string, dir = ""): Record<string, string | null> {
+	const result: Record<string, string | null> = {};
+	for (const entry of fs.readdirSync(path.join(ws, dir), { withFileTypes: true })) {
+		if (entry.name === ".git") continue;
+		const rel = path.join(dir, entry.name);
+		if (entry.isDirectory()) Object.assign(result, workingFiles(ws, rel));
+		else result[rel] = digest(path.join(ws, rel));
+	}
+	return result;
+}
+
+afterEach(() => {
+	while (temps.length > 0) fs.rmSync(temps.pop() as string, { recursive: true, force: true });
+});
+
+describe("gitChangedFiles with real Git repositories", () => {
+	const names = ["한글.ts", "with spaces.ts", " leading.ts", "trailing.ts ", "a -> b.ts", "ordinary.ts"];
+
+	it.each(names)("preserves the untracked path %j with core.quotePath=true", (file) => {
+		const ws = repo();
+		write(ws, file);
+
+		expect(gitChangedFiles(ws)).toEqual([file]);
+	});
+
+	it.each(names)("preserves the modified tracked path %j with core.quotePath=true", (file) => {
+		const ws = repo();
+		write(ws, file);
+		commit(ws);
+		write(ws, file, "export const value = 2;\n");
+
+		expect(gitChangedFiles(ws)).toEqual([file]);
+	});
+
+	it("continues to include deleted files", () => {
+		const ws = repo();
+		fs.rmSync(path.join(ws, "tracked.txt"));
+
+		expect(gitChangedFiles(ws)).toEqual(["tracked.txt"]);
+	});
+
+	it("returns only the rename destination once and keeps the following change", () => {
+		const ws = repo();
+		const source = "RM 원본.test.ts";
+		const destination = "tests/a 새파일 -> 이름.test.ts";
+		write(ws, source);
+		write(ws, "z-after.ts", "export const after = 1;\n");
+		commit(ws);
+		fs.mkdirSync(path.join(ws, "tests"));
+		git(ws, ["mv", source, destination]);
+		write(ws, "z-after.ts", "export const after = 2;\n");
+		// Check the real protocol ordering, including a source name that resembles status columns.
+		expect(git(ws, ["status", "--porcelain", "-z"])).toBe(`R  ${destination}\0${source}\0 M z-after.ts\0`);
+
+		expect(gitChangedFiles(ws)).toEqual([destination, "z-after.ts"]);
+	});
+
+	it("skips a copy source record without losing its independent modification or the next file", () => {
+		const ws = repo();
+		git(ws, ["config", "--local", "status.renames", "copies"]);
+		const original = Array.from({ length: 10 }, (_, i) => `export const value${i} = ${i};\n`).join("");
+		write(ws, "a-original.ts", original);
+		commit(ws);
+		write(ws, "b-copy.ts", original);
+		write(ws, "a-original.ts", original + "export const extra = 10;\n");
+		git(ws, ["add", "-A"]);
+		write(ws, "z-after.ts");
+		expect(git(ws, ["status", "--porcelain", "-z"])).toBe("M  a-original.ts\0C  b-copy.ts\0a-original.ts\0?? z-after.ts\0");
+
+		expect(gitChangedFiles(ws)).toEqual(["a-original.ts", "b-copy.ts", "z-after.ts"]);
+	});
+
+	it("returns an empty list for a clean repository", () => {
+		expect(gitChangedFiles(repo())).toEqual([]);
+	});
+
+	it("returns an empty list outside a Git repository", () => {
+		const ws = tempDir();
+		write(ws, "한글.ts");
+
+		expect(gitChangedFiles(ws)).toEqual([]);
+	});
+});
+
+describe("Git changes through project discovery and test suggestions", () => {
+	it.each([
+		["tests/한글.test.ts", "tests/한글.test.ts"],
+		["src/계산.ts", "tests/계산.test.ts"],
+	])("suggests the existing Korean test for %s", (changedFile, testFile) => {
+		const ws = nodeProject();
+		write(ws, changedFile, "export const value = 2;\n");
+		const changed = gitChangedFiles(ws);
+		const info = readProjectInfo(ws, changed);
+
+		expect(fs.existsSync(path.join(ws, testFile))).toBe(true);
+		expect(suggestTestCommands(changed, info).map((s) => s.command)).toEqual([`npx vitest run ${testFile}`, "npm test"]);
+	});
+
+	it("suggests a staged Korean rename destination rather than the removed source", () => {
+		const ws = nodeProject();
+		git(ws, ["mv", "tests/한글.test.ts", "tests/새파일.test.ts"]);
+		const changed = gitChangedFiles(ws);
+
+		expect(suggestTestCommands(changed, readProjectInfo(ws, changed)).map((s) => s.command)).toEqual([
+			"npx vitest run tests/새파일.test.ts", "npm test",
+		]);
+	});
+
+	it("leaves the index, working files and local/global configuration untouched", () => {
+		const ws = nodeProject();
+		git(ws, ["mv", "tests/한글.test.ts", "tests/새파일.test.ts"]);
+		write(ws, "src/계산.ts", "export const value = 2;\n");
+		write(ws, "untracked.ts");
+		const globalConfigs = process.env.GIT_CONFIG_GLOBAL ? [process.env.GIT_CONFIG_GLOBAL] : [
+			path.join(os.homedir(), ".gitconfig"),
+			path.join(process.env.XDG_CONFIG_HOME || path.join(os.homedir(), ".config"), "git", "config"),
+		];
+		const stateFiles = [path.join(ws, ".git", "index"), path.join(ws, ".git", "config"), ...globalConfigs];
+		const before = { files: workingFiles(ws), state: stateFiles.map(digest) };
+
+		const changed = gitChangedFiles(ws);
+		suggestTestCommands(changed, readProjectInfo(ws, changed));
+
+		expect({ files: workingFiles(ws), state: stateFiles.map(digest) }).toEqual(before);
+	});
+});

