 15	/** The shell command embedded in a checklist/verification line, or null when it is prose. */
 16	export function extractCommand(line: string): string | null {
 17		const text = stripTask(line.trim()).replace(/^-\s+/, "").trim();
 18		const ticked = text.match(/`([^`]+)`/);
 19		if (ticked) return ticked[1].trim();
 20		const first = text.split(/\s+/)[0] || "";
 21		if (RUNNER_PREFIXES.some((p) => text.startsWith(p)) || /^[\w.-]+(\.sh|\.ps1|\.cmd|\.bat)$/.test(first)) return text;
 22		return null;
 23	}
