 25	export interface VerificationEntry {
 26		stamp: string;
 27		command: string;
 28		exitCode: number | null;
 29		durationMs: number;
 30		note?: string;
 31	}
 32	
 33	export function formatVerificationLine(entry: VerificationEntry): string {
 34		const status = entry.exitCode === 0 ? "OK" : entry.exitCode === null ? "TIMEOUT" : `FAIL exit ${entry.exitCode}`;
 35		return `- ${entry.stamp} - \`${entry.command}\` → ${status} (${(entry.durationMs / 1000).toFixed(1)}s)${entry.note ? ` ${entry.note}` : ""}`;
 36	}
