 38	/** Append a line to `## 검증 로그`, creating the section at the end when missing. 줄바꿈은 보존한다. */
 39	export function appendVerificationLog(text: string, line: string): string {
 40		// 섹션 판정은 hasSection 하나로 — 자체 정규식은 CRLF 파일의 `## 검증 로그\r\n` 을 놓쳐 섹션을 중복 생성했다.
 41		if (hasSection(text, "검증 로그")) {
 42			// 기존 줄은 원본 그대로 다시 쓴다 — lines() 로 재조립하면 들여쓰기와 빈 줄이 사라진다.
 43			return writeSection(text, "검증 로그", [...sectionLines(text, "검증 로그"), line]);
 44		}
 45		const eol = detectEol(text);
 46		return restoreEol(normalizeEol(text).replace(/\s*$/, "") + `\n\n## 검증 로그\n${line}\n`, eol);
