 49	/** Tick the checklist line at `lineIndex` when it is unchecked. 줄바꿈은 보존한다. */
 50	export function checkLine(text: string, lineIndex: number): string {
 51		const eol = detectEol(text);
 52		const all = normalizeEol(text).split("\n");
 53		if (all[lineIndex] && /^- \[ \] /.test(all[lineIndex].trim())) all[lineIndex] = all[lineIndex].replace("- [ ] ", "- [x] ");
 54		return restoreEol(all.join("\n"), eol);
 55	}
