 63	/** Run a shell command in the workspace root, streaming output to the Vibe Code channel. */
 64	export function runShellCommand(host: CoreHost, command: string, cwd: string, timeoutMs = 10 * 60 * 1000): Promise<RunResult> {
 65		return new Promise((resolve) => {
 66			const started = Date.now();
 67			let output = "";
 68			host.output.show(true);
 69			host.output.appendLine(`\n$ ${command}   (cwd: ${cwd})`);
 70			const child = spawn(command, { cwd, shell: true, env: process.env, windowsHide: true });
 71			const onData = (chunk: Buffer) => {
 72				const text = chunk.toString("utf8");
 73				output += text;
 74				for (const line of text.split(/\r?\n/)) if (line) host.output.appendLine(`  ${line}`);
 75			};
 76			child.stdout?.on("data", onData);
 77			child.stderr?.on("data", onData);
 78			const timer = setTimeout(() => {
 79				child.kill();
 80				resolve({ exitCode: null, durationMs: Date.now() - started, output });
 81			}, timeoutMs);
 82			child.on("error", (error) => {
 83				clearTimeout(timer);
 84				host.output.appendLine(`  (spawn failed: ${error.message})`);
 85				resolve({ exitCode: 127, durationMs: Date.now() - started, output });
 86			});
 87			child.on("close", (code) => {
 88				clearTimeout(timer);
 89				host.output.appendLine(`→ exit ${code} (${((Date.now() - started) / 1000).toFixed(1)}s)`);
 90				resolve({ exitCode: code, durationMs: Date.now() - started, output });
 91			});
 92		});
 93	}
