101	async function runAndRecord(host: CoreHost, command: string, target: VerificationTarget | null): Promise<RunResult> {
102		const ws = workspaceRoot() || process.cwd();
103		const result = await runShellCommand(host, command, ws);
104		const entry: VerificationEntry = { stamp: kstStamp().human, command, exitCode: result.exitCode, durationMs: result.durationMs };
105		const line = formatVerificationLine(entry);
106		const touched: string[] = [];
107		const record = (file: string, tick?: number) => {
108			if (!fs.existsSync(file)) return;
109			let text = readUtf8(file);
110			text = appendVerificationLog(text, line);
111			if (tick !== undefined && result.exitCode === 0) text = checkLine(text, tick);
112			text = touchPlan(text, null, entry.stamp);
113			fs.writeFileSync(file, text, "utf8");
114			touched.push(path.basename(file));
115		};
116		if (target) record(target.file, target.lineIndex);
117		const paths = ensureWorkspacePaths(true);
118		if (paths && fs.existsSync(paths.current) && (!target || path.resolve(target.file) !== path.resolve(paths.current))) record(paths.current);
119		writeAudit(host, "plan", "runVerification", { command, exitCode: result.exitCode, durationMs: result.durationMs, recordedIn: touched });
120		const label = result.exitCode === 0 ? "통과" : result.exitCode === null ? "시간 초과" : `실패 (exit ${result.exitCode})`;
121		void (result.exitCode === 0 ? vscode.window.showInformationMessage : vscode.window.showWarningMessage)(`검증 ${label}: ${command}`);
122		return result;
123	}
