141	const TEST_FILE_RE = /(\.test\.|\.spec\.|_test\.go$|^test_.*\.py$|\/tests?\/|__tests__\/)/;
142	
143	/** Map changed source files to test commands. Pure; `info.existingFiles` holds workspace-relative paths. */
144	export function suggestTestCommands(changedFiles: string[], info: ProjectInfo): TestSuggestion[] {
145		const suggestions: TestSuggestion[] = [];
146		const seen = new Set<string>();
147		const add = (command: string, reason: string) => {
148			if (seen.has(command)) return;
149			seen.add(command);
150			suggestions.push({ command, reason });
151		};
152		const jsRunner = info.devDependencies.includes("vitest") ? "npx vitest run" : info.devDependencies.includes("jest") ? "npx jest" : info.packageScripts.test ? "npm test --" : "";
153		for (const raw of changedFiles) {
154			const file = raw.replace(/\\/g, "/");
155			const ext = path.posix.extname(file);
156			const dir = path.posix.dirname(file);
157			const base = path.posix.basename(file, ext);
158			if (TEST_FILE_RE.test(file)) {
159				if (/\.(ts|tsx|js|jsx|mjs)$/.test(file) && jsRunner) add(`${jsRunner} ${file}`, `변경된 테스트 파일`);
160				else if (file.endsWith("_test.go")) add(`go test ./${dir}/...`, `변경된 Go 테스트`);
161				else if (file.endsWith(".py")) add(`pytest ${file}`, `변경된 파이썬 테스트`);
162				continue;
163			}
164			if (/\.(ts|tsx|js|jsx|mjs)$/.test(file) && jsRunner) {
165				const candidates = [`${dir}/${base}.test${ext}`, `${dir}/${base}.spec${ext}`, `${dir}/__tests__/${base}.test${ext}`, `tests/unit/${base}.test.ts`, `tests/${base}.test${ext}`, `test/${base}.test${ext}`];
166				const hit = candidates.find((c) => info.existingFiles.has(c));
167				if (hit) add(`${jsRunner} ${hit}`, `${file} 의 테스트`);
168			} else if (file.endsWith(".go") && info.hasGoMod) {
169				add(`go test ./${dir === "." ? "" : dir + "/"}...`, `${file} 의 패키지`);
170			} else if (file.endsWith(".py") && info.hasPytest) {
171				const candidates = [`${dir}/test_${base}.py`, `tests/test_${base}.py`, `test/test_${base}.py`];
172				const hit = candidates.find((c) => info.existingFiles.has(c));
173				add(hit ? `pytest ${hit}` : "pytest", hit ? `${file} 의 테스트` : "전체 파이썬 테스트");
174			} else if (file.endsWith(".rs") && info.hasCargo) {
175				add("cargo test", `${file} (Rust)`);
176			}
177		}
178		if (changedFiles.length > 0) {
179			if (info.packageScripts.check) add("npm run check", "프로젝트 전체 검사 스크립트");
180			else if (info.packageScripts.test) add("npm test", "프로젝트 테스트 스크립트");
181			if (info.hasGoMod && changedFiles.some((f) => f.endsWith(".go"))) add("go test ./...", "전체 Go 테스트");
182		}
183		return suggestions;
184	}
