186	export function gitChangedFiles(ws: string): string[] {
187		try {
188			const out = execFileSync("git", ["--no-optional-locks", "status", "--porcelain", "-z", "--untracked-files=all"], { cwd: ws, encoding: "utf8", windowsHide: true });
189			const records = out.split("\0");
190			const files: string[] = [];
191			for (let i = 0; i < records.length; i++) {
192				const record = records[i];
193				if (!record) continue;
194				files.push(record.slice(3));
195				// Porcelain -z puts the destination first, then a separate source record for renames/copies.
196				if (/[RC]/.test(record.slice(0, 2))) i++;
197			}
198			return files;
199		} catch {
200			return [];
201		}
202	}
