204	export function readProjectInfo(ws: string, changed: string[]): ProjectInfo {
205		let packageScripts: Record<string, string> = {};
206		let devDependencies: string[] = [];
207		try {
208			const pkg = JSON.parse(readUtf8(path.join(ws, "package.json")));
209			packageScripts = pkg.scripts || {};
210			devDependencies = Object.keys({ ...(pkg.devDependencies || {}), ...(pkg.dependencies || {}) });
211		} catch {
212			// not a node project
213		}
214		const existing = new Set<string>();
215		const probe = (rel: string) => {
216			if (fs.existsSync(path.join(ws, rel))) existing.add(rel);
217		};
218		for (const raw of changed) {
219			const file = raw.replace(/\\/g, "/");
220			const ext = path.posix.extname(file);
221			const dir = path.posix.dirname(file);
222			const base = path.posix.basename(file, ext);
223			for (const c of [`${dir}/${base}.test${ext}`, `${dir}/${base}.spec${ext}`, `${dir}/__tests__/${base}.test${ext}`, `tests/unit/${base}.test.ts`, `tests/${base}.test${ext}`, `test/${base}.test${ext}`, `${dir}/test_${base}.py`, `tests/test_${base}.py`, `test/test_${base}.py`]) probe(c);
224		}
225		return {
226			packageScripts,
227			devDependencies,
228			hasGoMod: fs.existsSync(path.join(ws, "go.mod")),
229			hasPytest: fs.existsSync(path.join(ws, "pytest.ini")) || fs.existsSync(path.join(ws, "pyproject.toml")) || fs.existsSync(path.join(ws, "setup.cfg")),
230			hasCargo: fs.existsSync(path.join(ws, "Cargo.toml")),
231			existingFiles: existing,
232		};
233	}
