242	class VerificationCodeLensProvider implements vscode.CodeLensProvider {
243		provideCodeLenses(document: vscode.TextDocument): vscode.CodeLens[] {
244			const text = document.getText();
245			const result: vscode.CodeLens[] = [];
246			for (let i = 0; i < document.lineCount; i++) {
247				const line = document.lineAt(i).text;
248				if (!isTaskLine(line.trim()) && !/^- /.test(line.trim())) continue;
249				const sectionName = sectionOfLine(text, i);
250				if (!["검증 계획", "검증", "완료 기준"].includes(sectionName)) continue;
251				const command = extractCommand(line);
252				if (!command) continue;
253				result.push(new vscode.CodeLens(new vscode.Range(i, 0, i, 0), { title: "$(play) 검증 실행", command: "vibe-code.runVerification", arguments: [document.uri.toString(), i] }));
254			}
255			return result;
256		}
257	}
