259	export function registerVerification(host: CoreHost): void {
260		const { context } = host;
261		context.subscriptions.push(
262			vscode.languages.registerCodeLensProvider(SELECTOR, new VerificationCodeLensProvider()),
263			vscode.commands.registerCommand("vibe-code.runVerification", async (uriString: string, lineIndex: number) => {
264				const file = vscode.Uri.parse(uriString).fsPath;
265				if (!fs.existsSync(file)) return;
266				const line = readUtf8(file).split(/\r?\n/)[lineIndex] || "";
267				const command = extractCommand(line);
268				if (!command) {
269					void vscode.window.showWarningMessage("이 줄에서 실행할 명령을 찾지 못했습니다. 명령을 백틱(`)으로 감싸세요.");
270					return;
271				}
272				await runAndRecord(host, command, { file, lineIndex });
273			}),
274			vscode.commands.registerCommand("vibe-code.runVerificationCommand", async (commandArg?: unknown) => {
275				const paths = ensureWorkspacePaths();
276				if (!paths) return;
277				let command = typeof commandArg === "string" ? commandArg : "";
278				let target: VerificationTarget | null = null;
279				if (!command) {
280					const planFile = path.join(paths.plans, selectPlanName(paths));
281					const items: Array<vscode.QuickPickItem & { command: string; lineIndex?: number; file?: string }> = [];
282					if (fs.existsSync(planFile)) {
283						const all = readUtf8(planFile).split(/\r?\n/);
284						all.forEach((l, i) => {
285							const c = sectionOfLine(all.join("\n"), i) === "검증 계획" ? extractCommand(l) : null;
286							if (c) items.push({ label: `$(play) ${c}`, description: path.basename(planFile), command: c, lineIndex: i, file: planFile });
287						});
288					}
289					items.push({ label: "$(edit) 직접 입력...", command: "" });
290					const picked = await vscode.window.showQuickPick(items, { placeHolder: "실행할 검증 명령" });
291					if (!picked) return;
292					command = picked.command || (await vscode.window.showInputBox({ prompt: "실행할 명령", placeHolder: "npm test" })) || "";
293					if (!command) return;
294					target = picked.file ? { file: picked.file, lineIndex: picked.lineIndex } : null;
295				}
296				await runAndRecord(host, command, target);
297			}),
298			vscode.commands.registerCommand("vibe-code.suggestTests", async () => {
299				const ws = workspaceRoot();
300				if (!ws) {
301					void vscode.window.showWarningMessage("워크스페이스를 먼저 열어주세요.");
302					return;
303				}
304				const changed = gitChangedFiles(ws);
305				const suggestions = suggestTestCommands(changed, readProjectInfo(ws, changed));
306				if (suggestions.length === 0) {
307					void vscode.window.showInformationMessage(changed.length ? "변경 파일에 대응하는 테스트 명령을 찾지 못했습니다." : "git 기준 변경된 파일이 없습니다.");
308					return;
309				}
310				const picked = await vscode.window.showQuickPick(
311					suggestions.map((s) => ({ label: `$(beaker) ${s.command}`, description: s.reason, picked: true, command: s.command })),
312					{ canPickMany: true, placeHolder: `변경 파일 ${changed.length}개 → 실행할 검증 선택` },
313				);
314				if (!picked || picked.length === 0) return;
315				writeAudit(host, "plan", "suggestTests", { changed: changed.length, selected: picked.map((p) => p.command) });
316				for (const item of picked) {
317					const result = await runAndRecord(host, item.command, null);
318					if (result.exitCode !== 0) break;
319				}
320			}),
321		);
322		log(host, "verification runner registered");
323	}

